if __name__ == "__main__":
    import json, re
    from pathlib import Path
    data = json.loads((Path(__file__).resolve().parents[1] / "data/managed-content.json").read_text())
    pairs = [(c["subject"], c["title"]) for c in data["concepts"] if c["subject"].startswith("AP")]
    missing = [p for p in pairs if p not in WAVE6_SYNTHESIS]
    assert not missing, missing[:5]
    assert len(WAVE6_SYNTHESIS) == 202
    for p in sorted(set(pairs)):
        body = WAVE6_SYNTHESIS[p]
        wc = len(re.findall(r"\b\w+\b", body))
        assert body.startswith("## Unit Synthesis & Exam Day Notes"), p
        assert 400 <= wc <= 600, (p, wc)
    print(f"WAVE6_SYNTHESIS ok: {len(WAVE6_SYNTHESIS)} keys")
